+fn call(s: &mut Server, id: i64, name: &str, args: Value) -> Value {
+    let msg = json!({ "jsonrpc": "2.0", "id": id, "method": "tools/call", "params": { "name": name, "arguments": args } });
+    s.handle(&msg).expect("a response")["result"].clone()
+}
